record DeviceResponse(UUID id,UUID accountId,String accountName,String displayName,String clientType,String clientVersion,String status,String runtimeState,String stopReason,String pageContext,Instant lastHeartbeatAt,Instant lastSuccessfulSyncAt,String lastSuccessfulSyncType,Instant lastSuccessfulChatSyncAt,Instant lastSuccessfulJobSyncAt,Instant lastPauseAt,String lastPauseReason,Instant recoveryRequiredSince,Instant lastRecoveredAt,String recoveryStatus,Instant createdAt,Instant revokedAt){static DeviceResponse from(BrowserDevice d){String recoveryStatus=d.getRecoveryRequiredSince()!=null?"WAITING_RECOLLECTION":d.getLastSuccessfulChatSyncAt()==null?"NEVER_COLLECTED":d.getLastRecoveredAt()!=null?"RECOLLECTED":"HEALTHY";return new DeviceResponse(d.getId(),d.getBossAccount().getId(),d.getBossAccount().getDisplayName(),d.getDisplayName(),d.getClientType(),d.getClientVersion(),d.getStatus(),d.getRuntimeState(),d.getStopReason(),d.getPageContext(),d.getLastHeartbeatAt(),d.getLastSuccessfulSyncAt(),d.getLastSuccessfulSyncType(),d.getLastSuccessfulChatSyncAt(),d.getLastSuccessfulJobSyncAt(),d.getLastPauseAt(),d.getLastPauseReason(),d.getRecoveryRequiredSince(),d.getLastRecoveredAt(),recoveryStatus,d.getCreatedAt(),d.getRevokedAt());}}
