record UnreadObservationResponse(UUID id,UUID accountId,String accountName,String companyName,String anonymousKey,int unreadCount,boolean unread,boolean selectedConversationUnread,boolean jobRecognized,boolean previewRecognized,String observedJobTitle,String draftMode,String draftContent,String draftReason,Instant draftGeneratedAt,String draftQualification,UUID matchedJobPositionId,boolean manuallyMatched,Instant manualMatchedAt,List<String> draftBlockerCodes,Integer draftCompanyKnowledgeVersion,Integer draftJobKnowledgeVersion,String eligibilityStatus,String latestDirection,Instant latestMessageAt,Instant detailVerifiedAt,String conversationStage,ConversationSignals conversationSignals,String cycleTestStatus,String resumeReviewStatus,Instant cycleTestStartedAt,Instant cycleTestUpdatedAt,Instant resumeRequestedAt,Instant resumeApprovedAt,Instant contactExchangedAt,Instant humanTakeoverAt,String resumePipelineStatus,String resumePipelineReason,UUID resumeIntakeId,Instant resumePipelineUpdatedAt,String reviewStatus,String reviewedContent,String reviewNote,Instant reviewedAt,String fillStatus,Instant filledAt,String resolutionStatus,Instant resolvedAt,Instant firstSeenAt,Instant lastSeenAt){static UnreadObservationResponse from(BrowserUnreadObservation x){return new UnreadObservationResponse(x.getId(),x.getAccount().getId(),x.getAccount().getDisplayName(),x.getAccount().getCompany().getName(),x.getChatDigest().substring(0,12),x.getUnreadCount(),x.isUnread(),x.isSelectedConversationUnread(),x.getJobDigest()!=null,x.getPreviewDigest()!=null,x.getObservedJobTitle(),x.getDraftMode(),x.getDraftContent(),x.getDraftReason(),x.getDraftGeneratedAt(),x.getDraftQualification(),x.getMatchedJobPositionId(),x.getManualMatchJobPositionId()!=null,x.getManualMatchedAt(),x.getDraftBlockerCodes(),x.getDraftCompanyKnowledgeVersion(),x.getDraftJobKnowledgeVersion(),x.getEligibilityStatus(),x.getLatestDirection(),x.getLatestMessageAt(),x.getDetailVerifiedAt(),x.getConversationStage(),x.getConversationSignals(),x.getCycleTestStatus(),x.getResumeReviewStatus(),x.getCycleTestStartedAt(),x.getCycleTestUpdatedAt(),x.getResumeRequestedAt(),x.getResumeApprovedAt(),x.getContactExchangedAt(),x.getHumanTakeoverAt(),x.getResumePipelineStatus(),x.getResumePipelineReason(),x.getResumeIntakeId(),x.getResumePipelineUpdatedAt(),x.getReviewStatus(),x.getReviewedContent(),x.getReviewNote(),x.getReviewedAt(),x.getDraftFillStatus(),x.getDraftFilledAt(),x.getResolutionStatus(),x.getResolvedAt(),x.getFirstSeenAt(),x.getLastSeenAt());}}
